INSERT INTO `products` VALUES ('prod-026','hir-tile-plier','HIR Tile Plier','/images/product/Plier.png','Tools & Accessories','Manual tile cutting plier','HIR Tile Plier is a manual tool for cutting and shaping ceramic tiles. Tungsten carbide cutting wheel for clean cuts. Comfortable grip handle. Ideal for small cuts and curves.','Cutting Tool','Tile Cutting','Standard size','N/A','Ceramic Tiles','Metal with rubber grip','[\"Tungsten carbide wheel\", \"Clean cuts\", \"Comfortable grip\", \"For curves\", \"Portable\"]','{\"exterior\": [\"Field cutting\"], \"interior\": [\"Tile cutting\"]}','[]','',1,'HIR Tile Plier - Manual Ceramic Tile Cutting Tool','Manual tile cutting plier with tungsten carbide wheel. For clean cuts and curves.','','','[\"Tile cutting\", \"Small cuts\", \"Curved cuts\"]',43,'2026-08-12 16:00:13','2026-08-12 16:00:13');
INSERT INTO `products` VALUES ('prod-027','hir-tile-cleaner','HIR Tiles Cleaner','/images/product/Tiles-cleaner.png','Tools & Accessories','Post-grouting tile cleaner','HIR Tiles Cleaner is a specialized acidic cleaner for removing grout haze, cement stains, and efflorescence from tiles after installation. Safe for glazed tiles. Restores tile shine.','Cleaning Chemical','Post-Installation Cleaning','1 litre, 5 litre bottles','50-100 ml per m²','Glazed Tiles, Vitrified Tiles','Clear liquid','[\"Removes grout haze\", \"Cleans cement stains\", \"Safe for glazed tiles\", \"Restores shine\", \"Easy to use\"]','{\"exterior\": [\"Facade cleaning\"], \"interior\": [\"Post-grouting cleaning\"]}','[]','',1,'HIR Tiles Cleaner - Post-Grouting Tile Cleaning Solution','Removes grout haze and cement stains from tiles. Safe for glazed tiles, restores shine.','','','[\"Post-grouting\", \"Tile cleaning\", \"Stain removal\"]',44,'2026-08-12 16:00:13','2026-08-12 16:00:13');
INSERT INTO `blogs` VALUES ('blog-001','complete-guide-choosing-right-tile-adhesive','Complete Guide to Choosing the Right Tile Adhesive','/images/tiles adhesive.jpg','Selecting the right tile adhesive is crucial for long-lasting tile installations. Learn about different grades, applications, and how to choose the perfect adhesive for your project.','[{\"type\": \"text\", \"content\": \"Choosing the right tile adhesive can make the difference between a tile installation that lasts decades and one that fails within months. With various grades and types available, it\'s essential to understand what each offers.\"}, {\"type\": \"heading\", \"content\": \"Understanding Tile Adhesive Grades\"}, {\"type\": \"text\", \"content\": \"Tile adhesives are classified according to European standards (EN 12004) into different grades: C1, C2, with additional properties like T (reduced slip), E (extended open time), S (deformable), and F (fast setting).\"}, {\"type\": \"heading\", \"content\": \"C1 vs C2 Tile Adhesive\"}, {\"type\": \"text\", \"content\": \"C1 adhesives offer bond strength ≥0.5 N/mm², suitable for standard ceramic tiles on walls and floors. C2 adhesives provide ≥1.0 N/mm² bond strength, ideal for large format tiles, porcelain, natural stone, and exterior applications.\"}, {\"type\": \"heading\", \"content\": \"Special Properties to Consider\"}, {\"type\": \"list\", \"items\": [\"T (Reduced Slip): Prevents tiles from sliding during installation, especially important for wall tiling\", \"E (Extended Open Time): Provides longer working time, ideal for large areas or hot weather\", \"S1/S2 (Deformable): Flexible adhesives that accommodate substrate movement and thermal expansion\", \"F (Fast Setting): Quick-setting adhesives for fast-track projects, grout-ready in 3-4 hours\"]}, {\"type\": \"heading\", \"content\": \"Matching Adhesive to Tile Size\"}, {\"type\": \"text\", \"content\": \"Small tiles (up to 300×300mm): C1 or C1T grade adhesive. Medium tiles (300×600mm): C2TE grade recommended. Large format tiles (600×1200mm and above): C2TES1 or C2TES2 grade mandatory for proper support and flexibility.\"}, {\"type\": \"heading\", \"content\": \"Interior vs Exterior Applications\"}, {\"type\": \"text\", \"content\": \"Interior dry areas can use C1 grade adhesives. Wet areas (bathrooms, kitchens) require C2 with water resistance. Exterior applications demand C2TES1 or higher with weather resistance and flexibility to handle temperature variations.\"}, {\"type\": \"heading\", \"content\": \"HIR Tile Adhesive Range\"}, {\"type\": \"text\", \"content\": \"HIR Industries offers a complete range: ALPHA (C2TES2 for premium applications), BETA (C2TE for standard tiling), GAMMA (white adhesive for glass mosaics), DELTA (C1TE economical), and Flexi Plus (S1 flexible for moving substrates).\"}, {\"type\": \"heading\", \"content\": \"Common Mistakes to Avoid\"}, {\"type\": \"list\", \"items\": [\"Using standard adhesive for large format tiles - leads to sagging and poor bonding\", \"Ignoring substrate movement - choose flexible adhesives for balconies and timber floors\", \"Wrong trowel size - use manufacturer recommended notch size for proper coverage\", \"Exceeding open time - apply tiles within the specified open time for optimal bond\"]}, {\"type\": \"heading\", \"content\": \"Conclusion\"}, {\"type\": \"text\", \"content\": \"Investing in the right tile adhesive grade ensures long-lasting, trouble-free tile installations. Consider tile size, substrate type, exposure conditions, and application area when selecting your adhesive. For expert guidance, consult HIR Industries technical team.\"}]','HIR Technical Team','Tile Adhesive',1,'2026-01-15 00:00:00','Complete Guide to Choosing the Right Tile Adhesive | HIR Industries','Learn how to select the perfect tile adhesive for your project. Understand C1, C2 grades and special properties like flexibility and fast-setting.',1,'2026-08-12 16:28:21','2026-08-12 16:28:21');
INSERT INTO `blogs` VALUES ('blog-002','why-epoxy-grout-best-choice-kitchens-bathrooms','Why Epoxy Grout is the Best Choice for Kitchens and Bathrooms','/images/epoxy grout .avif','Discover why epoxy grout is superior to cement grout for wet areas. Learn about stain resistance, hygiene benefits, and long-term cost savings.','[{\"type\": \"text\", \"content\": \"When it comes to grouting tiles in kitchens and bathrooms, epoxy grout offers unmatched performance compared to traditional cement-based grout. Here\'s why it\'s worth the investment.\"}, {\"type\": \"heading\", \"content\": \"What is Epoxy Grout?\"}, {\"type\": \"text\", \"content\": \"Epoxy grout is a two-component system consisting of epoxy resin and hardener. Unlike cement grout, it contains no cement or water, making it completely non-porous and impervious to stains and moisture.\"}, {\"type\": \"heading\", \"content\": \"100% Stain Proof Performance\"}, {\"type\": \"text\", \"content\": \"Epoxy grout joints never absorb stains from coffee, wine, oil, turmeric, or any other kitchen spills. Unlike cement grout that discolors over time, epoxy grout maintains its original color for decades without sealing or special maintenance.\"}, {\"type\": \"heading\", \"content\": \"Superior Hygiene and Anti-Bacterial Properties\"}, {\"type\": \"text\", \"content\": \"The non-porous nature of epoxy grout prevents bacteria, mold, and fungus growth. This makes it ideal for hospitals, commercial kitchens, food processing units, and any area where hygiene is paramount.\"}, {\"type\": \"heading\", \"content\": \"Chemical and Acid Resistance\"}, {\"type\": \"text\", \"content\": \"Epoxy grout withstands exposure to harsh cleaning chemicals, acids, and alkalis without degradation. Perfect for areas that require frequent deep cleaning with strong disinfectants.\"}, {\"type\": \"heading\", \"content\": \"Zero Water Absorption\"}, {\"type\": \"text\", \"content\": \"With zero water absorption, epoxy grout prevents water seepage through joints, protecting the substrate from moisture damage. This is crucial in shower areas, swimming pools, and wet room applications.\"}, {\"type\": \"heading\", \"content\": \"Long-Term Cost Savings\"}, {\"type\": \"text\", \"content\": \"While epoxy grout costs more upfront, it eliminates the need for periodic sealing, re-grouting, or joint repairs that cement grout requires. Over 10-15 years, epoxy grout proves more economical.\"}, {\"type\": \"heading\", \"content\": \"Color Consistency and Aesthetics\"}, {\"type\": \"text\", \"content\": \"Available in 40+ colors, HIR Epoxy Grout offers vibrant, permanent color that never fades. You can match or contrast with tiles to create stunning visual effects. High-gloss epoxy variants provide a mirror-like finish.\"}, {\"type\": \"heading\", \"content\": \"Application Considerations\"}, {\"type\": \"list\", \"items\": [\"Requires professional application - working time is limited\", \"Surface must be thoroughly cleaned before application\", \"Best applied in controlled temperature conditions (15-35°C)\", \"Clean excess material immediately with proper cleaning solutions\"]}, {\"type\": \"heading\", \"content\": \"Where to Use Epoxy Grout\"}, {\"type\": \"text\", \"content\": \"Kitchen countertops and backsplash, bathroom walls and floors, shower areas, swimming pools, commercial kitchens, hospitals and healthcare facilities, food processing areas, laboratories, and high-traffic commercial spaces.\"}, {\"type\": \"heading\", \"content\": \"HIR Epoxy Grout Range\"}, {\"type\": \"text\", \"content\": \"HIR Industries offers premium epoxy grout in matte and high-gloss finishes with 40+ color options. Certified for food contact areas and backed by comprehensive technical support.\"}]','HIR Technical Team','Epoxy Grout',1,'2026-01-20 00:00:00','Why Epoxy Grout is Best for Kitchens & Bathrooms | HIR Industries','Discover the benefits of epoxy grout: 100% stain-proof, anti-bacterial, zero water absorption. Perfect for kitchens, bathrooms, and wet areas.',2,'2026-08-12 16:28:21','2026-08-12 16:28:21');
INSERT INTO `blogs` VALUES ('blog-003','waterproofing-basics-protect-your-home-from-water-damage','Waterproofing Basics: Protect Your Home from Water Damage','/images/water proffing.jpg','Learn essential waterproofing techniques for terraces, bathrooms, and basements. Prevent costly water damage with proper waterproofing systems.','[{\"type\": \"text\", \"content\": \"Water damage is one of the most common and costly problems homeowners face. Proper waterproofing during construction and timely maintenance can prevent leakage, seepage, and structural damage.\"}, {\"type\": \"heading\", \"content\": \"Why Waterproofing is Critical\"}, {\"type\": \"text\", \"content\": \"Water ingress leads to concrete deterioration, steel reinforcement corrosion, paint peeling, fungal growth, and dampness. Waterproofing is not an expense—it\'s an investment that protects your property value and ensures occupant health.\"}, {\"type\": \"heading\", \"content\": \"Types of Waterproofing Systems\"}, {\"type\": \"text\", \"content\": \"Cementitious waterproofing uses flexible cement-based coatings, ideal for terraces and bathrooms. Liquid membrane waterproofing applies acrylic or polyurethane coatings for seamless protection. Bituminous waterproofing suits basements and foundations with its excellent water resistance.\"}, {\"type\": \"heading\", \"content\": \"Terrace and Roof Waterproofing\"}, {\"type\": \"text\", \"content\": \"Terraces are the most vulnerable areas. Clean the surface thoroughly, repair cracks with flexible sealant, apply primer coat, then 2-3 coats of waterproofing membrane. Pay special attention to corners, edges, and pipe penetrations.\"}, {\"type\": \"heading\", \"content\": \"Bathroom Waterproofing\"}, {\"type\": \"text\", \"content\": \"Waterproof bathrooms before tiling to prevent leakage to floors below. Apply flexible cementitious waterproofing on walls up to 6 feet height and entire floor. Corners, pipe junctions, and floor drains need extra coats and sealing tape reinforcement.\"}, {\"type\": \"heading\", \"content\": \"Basement and Foundation Waterproofing\"}, {\"type\": \"text\", \"content\": \"Basements face hydrostatic pressure from groundwater. Use bituminous or crystalline waterproofing on external walls during construction. For internal treatment, negative-side waterproofing products resist water pressure from outside.\"}, {\"type\": \"heading\", \"content\": \"Common Waterproofing Mistakes\"}, {\"type\": \"list\", \"items\": [\"Skipping surface preparation - poor bonding leads to failure\", \"Insufficient coating thickness - apply recommended number of coats\", \"Ignoring cracks and joints - these are primary leakage points\", \"Not allowing proper curing time between coats\", \"Using wrong product for the application\"]}, {\"type\": \"heading\", \"content\": \"Heat Reflective Waterproofing\"}, {\"type\": \"text\", \"content\": \"HIR Heat X is a revolutionary waterproofing solution that also reduces roof temperature by up to 15°C. The heat-reflective coating saves energy costs by reducing air conditioning load while providing excellent waterproofing.\"}, {\"type\": \"heading\", \"content\": \"Maintenance and Inspection\"}, {\"type\": \"text\", \"content\": \"Inspect waterproofing annually before monsoon. Check for cracks, blisters, or peeling. Clean drains and remove debris. Apply touch-up coats every 3-5 years to maintain protection.\"}, {\"type\": \"heading\", \"content\": \"HIR Waterproofing Solutions\"}, {\"type\": \"text\", \"content\": \"HIR Shield (flexible cementitious), HIR Super Coat (acrylic), HIR Nero Coat (bituminous), HIR Heat X (heat reflective), HIR Salt X (anti-efflorescence), and HIR Crack Lock (crack sealant) - complete waterproofing system for every need.\"}, {\"type\": \"heading\", \"content\": \"Conclusion\"}, {\"type\": \"text\", \"content\": \"Don\'t wait for leakage to appear. Waterproof during construction or renovation. Choose the right system for each area, ensure proper application, and maintain regularly. For technical guidance, consult HIR Industries waterproofing experts.\"}]','HIR Technical Team','Waterproofing',1,'2026-01-25 00:00:00','Complete Waterproofing Guide for Homes | HIR Industries','Learn waterproofing basics for terraces, bathrooms, and basements. Prevent water damage with proper techniques and materials.',3,'2026-08-12 16:28:21','2026-08-12 16:28:21');
INSERT INTO `blogs` VALUES ('blog-004','installing-large-format-tiles-tips-and-best-practices','Installing Large Format Tiles: Tips and Best Practices','/images/applications-tiler.jpg','Large format tiles create stunning, modern spaces but require special installation techniques. Learn the essential tips for successful large tile installation.','[{\"type\": \"text\", \"content\": \"Large format tiles (600×1200mm, 800×1600mm, and larger) are trending in modern architecture for their sleek, seamless appearance. However, they require specialized installation techniques and materials.\"}, {\"type\": \"heading\", \"content\": \"Why Large Format Tiles are Different\"}, {\"type\": \"text\", \"content\": \"Large tiles have less tolerance for substrate irregularities. Any lippage becomes highly visible. They are heavier, requiring stronger adhesive bonding. Tile warpage is more apparent in large sizes, demanding careful selection and handling.\"}, {\"type\": \"heading\", \"content\": \"Substrate Preparation is Critical\"}, {\"type\": \"text\", \"content\": \"The substrate must be perfectly flat with maximum 3mm variation per 2 meters. Use self-leveling compounds to correct irregularities. Any bump or depression will telegraph through large tiles. Check substrate strength—it must support the tile weight.\"}, {\"type\": \"heading\", \"content\": \"Choosing the Right Adhesive\"}, {\"type\": \"text\", \"content\": \"Standard C1 adhesive is insufficient for large format tiles. Use C2TES2 grade adhesive like HIR ALPHA that offers high bond strength (≥1 N/mm²), reduced slip properties, and extended open time for easier installation.\"}, {\"type\": \"heading\", \"content\": \"Back Buttering is Mandatory\"}, {\"type\": \"text\", \"content\": \"Apply adhesive on both the substrate (using notched trowel) and the back of the tile (using flat trowel). This ensures 100% contact and eliminates voids that cause hollow sounds and potential cracking.\"}, {\"type\": \"heading\", \"content\": \"Trowel Size and Technique\"}, {\"type\": \"text\", \"content\": \"Use larger notch trowels (10-12mm) for large format tiles. Hold the trowel at 45° angle to create consistent ridges. Comb in one direction to avoid air pockets. Maintain consistent bed thickness across the floor.\"}, {\"type\": \"heading\", \"content\": \"Handling and Placement\"}, {\"type\": \"list\", \"items\": [\"Check each tile for warpage before installation - reject if warpage exceeds 2mm\", \"Use mechanical lifting aids for very large tiles to prevent injury\", \"Place tiles gently, don\'t slide into position as this removes adhesive\", \"Use tile leveling systems to prevent lippage between adjacent tiles\", \"Tap with rubber mallet to ensure full adhesive contact\"]}, {\"type\": \"heading\", \"content\": \"Joint Width Considerations\"}, {\"type\": \"text\", \"content\": \"Minimum 3mm joint width recommended for large format tiles to accommodate thermal expansion. Don\'t attempt zero-joint installation—it will lead to tile lifting and cracking. Use high-quality spacers for consistency.\"}, {\"type\": \"heading\", \"content\": \"Expansion Joints\"}, {\"type\": \"text\", \"content\": \"Place expansion joints every 6-8 meters in both directions for large tile installations. Around the perimeter, maintain 5-8mm gap filled with flexible sealant. This prevents stress build-up from thermal movement.\"}, {\"type\": \"heading\", \"content\": \"Grouting Large Format Tiles\"}, {\"type\": \"text\", \"content\": \"Use epoxy grout for best results—it provides superior strength and prevents staining. Alternatively, use high-quality cement grout with polymer additives. Remove all spacers and clean joints thoroughly before grouting.\"}, {\"type\": \"heading\", \"content\": \"Common Problems and Solutions\"}, {\"type\": \"text\", \"content\": \"Hollow sounds indicate voids under tile—caused by insufficient adhesive or improper back buttering. Lippage between tiles results from uneven substrate or inadequate leveling systems. Cracking occurs from substrate movement—use flexible adhesive in these areas.\"}, {\"type\": \"heading\", \"content\": \"Conclusion\"}, {\"type\": \"text\", \"content\": \"Large format tile installation demands meticulous preparation, right materials, and skilled execution. Invest in premium adhesives like HIR ALPHA, proper tools, and experienced installers. The result is a stunning, long-lasting floor or wall.\"}]','HIR Technical Team','Tile Adhesive',1,'2026-02-01 00:00:00','How to Install Large Format Tiles - Complete Guide | HIR Industries','Learn professional techniques for installing large format tiles. Substrate prep, adhesive selection, back buttering, and avoiding common mistakes.',4,'2026-08-12 16:28:21','2026-08-12 16:28:21');
INSERT INTO `blogs` VALUES ('blog-005','ultimate-guide-tile-and-grout-maintenance','The Ultimate Guide to Tile and Grout Maintenance','/images/tiler-working-renovation-apartment (1).jpg','Keep your tiles looking new for years with proper cleaning and maintenance. Expert tips for ceramic, porcelain, and natural stone tiles.','[{\"type\": \"text\", \"content\": \"Beautiful tile installations can lose their appeal without proper maintenance. Regular cleaning and correct techniques will keep your tiles and grout looking pristine for decades.\"}, {\"type\": \"heading\", \"content\": \"Daily Cleaning Routine\"}, {\"type\": \"text\", \"content\": \"Sweep or vacuum tiles daily to remove dirt and grit that can scratch the surface. Damp mop with plain water or mild pH-neutral cleaner. Avoid harsh acidic or alkaline cleaners for daily use—they degrade grout over time.\"}, {\"type\": \"heading\", \"content\": \"Deep Cleaning Techniques\"}, {\"type\": \"text\", \"content\": \"For thorough cleaning, use a soft brush and mild detergent solution. For stubborn stains on glazed tiles, specialized tile cleaners work best. Never use steel wool or abrasive scrubbers—they scratch the glaze permanently.\"}, {\"type\": \"heading\", \"content\": \"Grout Maintenance\"}, {\"type\": \"text\", \"content\": \"Cement grout is porous and absorbs stains. Clean regularly with grout brush and mild cleaner. For heavy staining, use oxygen bleach-based cleaners. Avoid chlorine bleach—it weakens grout. Seal cement grout annually to prevent staining.\"}, {\"type\": \"heading\", \"content\": \"Epoxy Grout Advantage\"}, {\"type\": \"text\", \"content\": \"Epoxy grout joints never require sealing or special maintenance. Simply wipe clean with any household cleaner. They resist all stains—coffee, wine, turmeric, oil—without discoloration. This is why epoxy grout is the best investment for kitchens and bathrooms.\"}, {\"type\": \"heading\", \"content\": \"Removing Specific Stains\"}, {\"type\": \"list\", \"items\": [\"Oil and grease: Alkaline degreaser or baking soda paste\", \"Coffee, tea, wine: Hydrogen peroxide or oxygen bleach\", \"Rust stains: Commercial rust remover (avoid on marble)\", \"Soap scum: Vinegar solution (avoid on natural stone)\", \"Hard water marks: Mild acid cleaner or lime scale remover\"]}, {\"type\": \"heading\", \"content\": \"Natural Stone Care\"}, {\"type\": \"text\", \"content\": \"Marble, granite, and limestone require special care. Never use acidic cleaners (vinegar, lemon)—they etch natural stone. Use pH-neutral stone cleaners only. Seal natural stone tiles and grout every 6-12 months to prevent staining and moisture absorption.\"}, {\"type\": \"heading\", \"content\": \"Preventing Damage\"}, {\"type\": \"text\", \"content\": \"Use door mats to trap dirt before it reaches tiles. Felt pads under furniture prevent scratches. Wipe spills immediately—especially acidic liquids on natural stone. Avoid dragging heavy objects across tile floors.\"}, {\"type\": \"heading\", \"content\": \"Shower and Wet Area Maintenance\"}, {\"type\": \"text\", \"content\": \"Squeegee shower walls after each use to prevent water spots and soap buildup. Ensure adequate ventilation to prevent mold growth. Clean glass shower doors weekly with glass cleaner. Check grout and sealant joints annually for deterioration.\"}, {\"type\": \"heading\", \"content\": \"Professional Cleaning and Re-grouting\"}, {\"type\": \"text\", \"content\": \"Consider professional steam cleaning every 1-2 years for deep restoration. If cement grout is severely stained or crumbling, remove and re-grout. Alternatively, apply epoxy grout over existing cement grout for permanent solution.\"}, {\"type\": \"heading\", \"content\": \"HIR Maintenance Products\"}, {\"type\": \"text\", \"content\": \"HIR Tiles Cleaner effectively removes grout haze, cement stains, and efflorescence after installation. For ongoing care, use mild pH-neutral cleaners and avoid harsh chemicals that damage tiles and grout over time.\"}, {\"type\": \"heading\", \"content\": \"Conclusion\"}, {\"type\": \"text\", \"content\": \"Proper maintenance preserves your tile investment and keeps spaces hygienic and attractive. Establish a regular cleaning routine, use appropriate products, and address problems early. For best results, choose epoxy grout during installation—it eliminates most maintenance concerns.\"}]','HIR Technical Team','Tile Maintenance',1,'2026-02-05 00:00:00','Complete Tile & Grout Maintenance Guide | HIR Industries','Expert tips for cleaning and maintaining ceramic, porcelain, and natural stone tiles. Keep your tiles looking new for years.',5,'2026-08-12 16:28:21','2026-08-12 16:28:21');
